-- 40 Moonlit Study: turns the fan, lets the moon drift, and switches the
-- lamp and the fan. Every pattern of light is a cookie the light shines
-- through (`cookie` on the light); turning a light turns its pattern.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/40-moonlit-study.scene"
local post_on = nav.post_all_on(SCENE)
local captions = true
local moon, fan, lamp, glow, status
local t, spin = 0, 0
local fan_on, lamp_on = true, true
local moon_x, moon_y

local function refresh()
    if status then
        UI.set_text(status, "lamp " .. (lamp_on and "on" or "off") .. "   fan " .. (fan_on and "turning" or "still"))
    end
end

function init(entity)
    moon = Entity.find_by_name("Moon")
    fan = Entity.find_by_name("Fan")
    lamp = Entity.find_by_name("Lamp")
    glow = Entity.find_by_name("LampGlow")
    status = Entity.find_by_name("Status")
    if moon then moon_x, moon_y = Transform.get_position(moon) end
    refresh()
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    if Input.is_key_just_pressed("L") then
        lamp_on = not lamp_on
        if lamp then Lighting.set_intensity(lamp, lamp_on and 2.0 or 0) end
        if glow then Sprite.set_color(glow, 1.0, 0.6, 0.21, lamp_on and 0.7 or 0) end
        refresh()
    end
    if Input.is_key_just_pressed("F") then
        fan_on = not fan_on
        refresh()
    end
    -- The fan's blades sweep round; its light turns with them.
    if fan and fan_on then
        spin = spin + dt * 2.2
        Transform.set_rotation(fan, spin)
    end
    -- The moon drifts: the window's panes slide and lean across the floor.
    if moon and moon_x then
        local k = math.sin(t * 0.12)
        Transform.set_rotation(moon, k * 0.18)
        Transform.set_position(moon, moon_x + k * 20, moon_y)
    end
end
